for(const q of records){if(ids.has(q.id)||sources.has(identity(q)))continue;q.question=question(q);if(q.keyImageIds?.length)q.answer='<div class="scsa-official-key">'+q.keyImageIds.map(id=>panel(q,id)).join('')+'</div>'+q.answer;bank.push(q);ids.add(q.id);sources.add(identity(q));if(window.UpperSchoolCourses){const list=window.UpperSchoolCourses[q.area]=window.UpperSchoolCourses[q.area]||[];let c=list.find(c=>c.name===q.course);if(!c)list.push({name:q.course,types:['ATAR']});else if(!c.types.includes('ATAR'))c.types.push('ATAR');}}
